// --- Global Patch for L.MarkerCluster ---

// Store the original internal method for creating an icon.
const _oldInitIcon = L.MarkerCluster.prototype._initIcon;

// Override the method with our custom logic.
L.MarkerCluster.prototype._initIcon = function () {
    // Run the original method first to let it create the icon element.
    _oldInitIcon.call(this);

    // Now, access the newly created element (this._icon) and modify it directly.
    if (this._icon) {
        this._icon.setAttribute('tabindex', '-1');
        this._icon.setAttribute('focusable', 'false');
        // We can also remove the 'role' as it's not meant to be a user-interactive 'button'.
        this._icon.removeAttribute('role');
    }
};
