/**
 * Logs a custom event to Google Analytics (GA4).
 * @param {string} eventName - The name of the event (e.g., 'select_sector', 'tract_interaction').
 * @param {object} params - Additional parameters for the event.
 */
function logGaEvent(eventName, params = {}) {
    if (typeof window.gtag === 'function') {
        window.gtag('event', eventName, params);
    } else {
        console.warn('GA4 not initialized, skipping event:', eventName, params);
    }
}

/**
 * Saves the last viewed tract details to LocalStorage for the Incentive Calculator.
 * @param {object} properties - The GeoJSON properties of the tract.
 */
function saveLastViewedTract(properties) {
    if (!properties) return;
    
    const tractData = {
        geoid: properties.GEOID,
        tract_name: properties.tract_name,
        county_name: properties.county_name,
        timestamp: new Date().toISOString()
    };
    
    try {
        localStorage.setItem('md_business_compass_last_tract', JSON.stringify(tractData));
    } catch (e) {
        console.warn('Could not save tract to local storage', e);
    }
}

