function createPointLayer(data, layerName) {
    const markers = L.markerClusterGroup({
        clusterPane: 'clusterTopPane',
        disableClusteringAtZoom: 10,
        spiderfyOnMaxZoom: false,
        iconCreateFunction: createCustomClusterIcon
    });

    markers.on('animationend', function () { disableMapLayerFocus(this); });

    const config = pointLayerConfigs[layerName] || { color: '#808080', borderColor: '#444' };
    const pointStyle = { radius: 6, fillColor: config.color, color: config.borderColor, weight: 3, opacity: 0.5, fillOpacity: 1 };

    if (data.type === 'FeatureCollection' && data.features) {
        const geojsonLayerForPoints = L.geoJSON(data, {
            filter: function(feature) {
                if (layerName === 'grocery') return feature.properties.quality > 1;
                return true; 
            },
            pointToLayer: function(feature, latlng) {
                return L.circleMarker(latlng, {...pointStyle, pane: 'clusterTopPane', markerType: layerName });
            },
            onEachFeature: function(feature, layer) {
                const p = feature.properties;
                let c = '';
                if(layerName==='childcare') {
                    c=`<div class="font-bold text-lg leading-tight">${p.gen_listing_name_original_text||'N/A'}</div><div class="text-sm text-slate-600 mt-1"><strong>Capacity (Under 6):</strong> ${p.licensed_capacity_under6||'N/A'} seats</div>`;
                } else if(layerName==='grocery') {
                    const q = p.quality;
                    const labels = { 2: 'Convenience', 3: 'Specialty foods', 4: 'Specialty foods', 5: 'Fresh produce' };
                    const qText = labels[q] || (q ? `Quality: ${q}` : 'N/A');
                    c=`<div class="font-bold text-lg leading-tight">${p.name||'N/A'}</div><div class="text-sm text-slate-600 mt-1"><strong>Type:</strong> ${p.tag_label||'N/A'}</div><div class="text-sm text-slate-600"><strong>Category:</strong> ${qText}</div>`;
                } else {
                    c=`<div class="font-bold text-lg leading-tight">${p.name||'N/A'}</div>`;
                }
                layer.bindPopup(c);
            }
        });
        markers.addLayer(geojsonLayerForPoints);
    }
    return markers;
}

async function preloadPolygonLayers() {
    const overlayConfigs = OVERLAY_CONFIG.filter(c => c.type === 'polygon');
    const loadingPromises = overlayConfigs.map(async (cfg) => {
        const layerName = cfg.name;
        const url = cfg.url;
        if (overlayLayers[layerName]) return;
        try {
            const response = await fetch(url);
            if (!response.ok) throw new Error(`Failed to pre-load ${url}`);
            const data = await response.json();
            const style = incentiveStyles[layerName] || { color: '#000000', weight: 2 };
            const layer = L.geoJSON(data, { style: {...style, pane: 'incentivePane' }, interactive: false });
            overlayLayers[layerName] = layer;
        } catch (error) {
            console.error(`Error pre-loading layer '${layerName}':`, error);
        }
    });
    try { await Promise.all(loadingPromises); } catch (e) { console.error("Pre-load error", e); }
}

async function preloadPointLayers() {
    const pointConfigs = OVERLAY_CONFIG.filter(c => c.type === 'point');
    const loadingPromises = pointConfigs.map(async (cfg) => {
        const layerName = cfg.name;
        const url = cfg.url;
        if (overlayLayers[layerName]) return;

        try {
            const response = await fetch(url);
            if (!response.ok) throw new Error(`Failed to pre-load ${url}`);
            const data = await response.json();
            
            overlayLayers[layerName] = createPointLayer(data, layerName);
        } catch (error) { console.error(`Error pre-loading point layer '${layerName}':`, error); }
    });
    await Promise.all(loadingPromises);
}

// --- CORE HELPER FUNCTIONS (GLOBAL) ---
function safeParseFloat(value, defaultValue = null) {
    const parsed = parseFloat(value);
    return isNaN(parsed) ? defaultValue : parsed;
}
const formatPercent = (val) => `${(safeParseFloat(val, 0) * 100).toFixed(1)}%`;
const formatPercentInteger = (val) => `${(safeParseFloat(val, 0) * 100).toFixed(0)}%`;
const formatCurrency = (val) => `$${Math.round(safeParseFloat(val, 0)).toLocaleString()}`;
const formatNumber = (val) => (val != null) ? Math.round(safeParseFloat(val)).toLocaleString() : 'N/A';
const formatK = (val) => {
    const num = safeParseFloat(val, 0);

    if (num >= 1000) {
        const valInK = num / 1000;
        const formattedNum = valInK.toLocaleString('en-US', {
            maximumFractionDigits: 1,
        });
        return `${formattedNum}k`;
    }
    
    // Fallback to standard number formatting for numbers less than 1000
    return formatNumber(num); 
};
const formatValue = (val) => (val != null) ? val : 'N/A';

function safeMatch(string, regex, index = 1, fallback = 'N/A') {
    if (typeof string !== 'string') return fallback; // Extra safety check
    const match = string.match(regex);
    // Return the matched group if it exists, otherwise return the fallback
    return (match && match[index]) ? match[index] : fallback;
}

// --- PAGINATION HELPER ---
function renderPagination(totalPages, currentPage, containerId, layerName) {
    if (totalPages <= 1) return ''; // No pagination needed

    const maxButtons = 5;
    let pages = [];
    
    // Previous button
    pages.push(`
        <button 
            class="usa-button usa-button--outline usa-button--icon text-sm w-8 h-8 p-0 ${currentPage === 1 ? 'opacity-50 cursor-not-allowed' : ''}" 
            aria-label="Previous page"
            ${currentPage === 1 ? 'disabled' : ''}
            onclick="updateProviderPage('${layerName}', ${currentPage - 1})">
            <svg class="usa-icon" aria-hidden="true" role="img" fill="currentColor" viewBox="0 0 24 24"><path d="M15.41 7.41 14 6l-6 6 6 6 1.41-1.41L10.83 12z"></path></svg>
        </button>
    `);

    let startPage = 1;
    let endPage = totalPages;

    if (totalPages > maxButtons) {
        let half = Math.floor(maxButtons / 2);
        if (currentPage <= half) {
            startPage = 1;
            endPage = maxButtons - 1; // 1, 2, 3, 4, 5, ..., {last}
        } else if (currentPage + half >= totalPages) {
            startPage = totalPages - (maxButtons - 2); // {1}, ..., {n-4}, {n-3}, {n-2}, {n-1}, {n}
            endPage = totalPages;
        } else {
            startPage = currentPage - (half - 1); // {1}, ..., {c-1}, {c}, {c+1}, ..., {last}
            endPage = currentPage + (half - 1);
        }
    }

    // Add first page if not in range
    if (startPage > 1) {
        pages.push(`
            <button class="usa-button usa-button--outline text-sm w-8 h-8 p-2" onclick="updateProviderPage('${layerName}', 1)">
                1
            </button>
        `);
        if (startPage > 2) {
             pages.push(`<span class="flex items-center justify-center text-sm w-8 h-8 text-slate-700">...</span>`);
        }
    }

    // Add numbered pages
    for (let i = startPage; i <= endPage; i++) {
        if (i === currentPage) {
            pages.push(`
                <button class="usa-button text-sm w-8 h-8 p-2 underline" aria-current="page" onclick="updateProviderPage('${layerName}', ${i})">
                    ${i}
                </button>
            `);
        } else {
            pages.push(`
                <button class="usa-button usa-button--outline text-sm w-8 h-8 p-2" onclick="updateProviderPage('${layerName}', ${i})">
                    ${i}
                </button>
            `);
        }
    }

    // Add last page if not in range
    if (endPage < totalPages) {
        if (endPage < totalPages - 1) {
            pages.push(`<span class="flex items-center justify-center text-sm w-8 h-8 text-slate-700">...</span>`);
        }
        pages.push(`
            <button class="usa-button usa-button--outline text-sm w-8 h-8 p-2" onclick="updateProviderPage('${layerName}', ${totalPages})">
                ${totalPages}
            </button>
        `);
    }

    // Next button
    pages.push(`
        <button 
            class="usa-button usa-button--outline usa-button--icon text-sm w-8 h-8 p-0 ${currentPage === totalPages ? 'opacity-50 cursor-not-allowed' : ''}" 
            aria-label="Next page"
            ${currentPage === totalPages ? 'disabled' : ''}
            onclick="updateProviderPage('${layerName}', ${currentPage + 1})">
            <svg class="usa-icon" aria-hidden="true" role="img" fill="currentColor" viewBox="0 0 24 24"><path d="M10 6 8.59 7.41 13.17 12l-4.58 4.59L10 18l6-6z"></path></svg>
        </button>
    `);


    return `<nav aria-label="Pagination" class="flex justify-center items-center gap-1 mt-8">${pages.join('')}</nav>`;
}

// --- PAGINATION CLICK HANDLER ---
function updateProviderPage(layerName, page) {
    const listContainer = document.getElementById(`provider-list-container-${layerName}`);
    if (!listContainer) return;
    
    // Get all items and hide them
    const allItems = listContainer.querySelectorAll('li[data-provider-item="true"]');
    allItems.forEach(item => item.classList.add('hidden'));

    // Calculate new range
    const itemsPerPage = 10;
    const startIndex = (page - 1) * itemsPerPage;
    const endIndex = page * itemsPerPage;
    const totalItems = allItems.length;

    // Show items for the new page
    const itemsToShow = Array.from(allItems).slice(startIndex, endIndex);
    itemsToShow.forEach(item => item.classList.remove('hidden'));

    // Update pagination text
    const paginationText = listContainer.querySelector('.pagination-text');
    if (paginationText) {
        paginationText.textContent = `Showing ${startIndex + 1}-${Math.min(endIndex, totalItems)} of ${totalItems} locations`;
    }

    // Re-render pagination controls
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    const navContainer = listContainer.querySelector('.pagination-nav-container');
    if (navContainer) {
        navContainer.innerHTML = renderPagination(totalPages, page, `provider-list-container-${layerName}`, layerName);
    }

    const contentWrapper = listContainer.closest('.usa-accordion__content');
    if (contentWrapper) {
        // Use setTimeout to wait for the DOM to re-render
        // before calculating the new scrollHeight
        setTimeout(() => {
            contentWrapper.style.maxHeight = contentWrapper.scrollHeight + 'px';
        }, 0);
    }
}

