/**
 * Positions the global map tooltip based on a mouse event.
 */
function positionGlobalMapTooltip(e) {
    // This is the exact logic from your 'mousemove' handler
    const mapSize = map.getSize();
    
    // Hardcoded values to prevent reflows
    const tooltipWidth = 280;  // From your CSS
    const tooltipHeight = 120; // An approximation of the tooltip's height
    const gap = 15;            // Your cursor buffer
    
    const pos = map.mouseEventToContainerPoint(e.originalEvent);
    let x, y;
    
    // --- X POSITION (Horizontal) ---
    let x_right = pos.x + gap;
    if (x_right + tooltipWidth > mapSize.x) {
        x = pos.x - tooltipWidth - gap;
    } else {
        x = x_right;
    }

    // --- Y POSITION (Vertical) ---
    let y_bottom = pos.y + gap;
    if (y_bottom + tooltipHeight + 40 > mapSize.y) { // Using your 40px buffer
        y = pos.y - tooltipHeight - gap;
    } else {
        y = y_bottom;
    }

    // Set the final position
    L.DomUtil.setPosition(globalTooltipElement, new L.Point(x, y));
}


/**
 * Forces all map tooltips (hover-tooltips and popups) to close.
 * Call this when a UI panel is opened to prevent overlap.
 */
function forceCloseAllTooltips() {
    // Hide the custom "on-hover" global tooltip
    if (globalTooltipElement) {
        L.DomUtil.addClass(globalTooltipElement, 'hidden');
    }
    
    // Close any active Leaflet popup (e.g., from a marker)
    if (map) {
        map.closePopup();
    }
}

/**
 * Positions the global floating tooltip relative to a trigger element.
 * This function calculates the best position (top or bottom) and
 * handles viewport collisions.
 */
function positionTooltip() {
    if (!floatingTooltip || !tooltipTrigger) return;

    const triggerRect = tooltipTrigger.getBoundingClientRect();
    const tooltipRect = floatingTooltip.getBoundingClientRect();
    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;
    const gap = 8; // 8px gap

    let top, left;

    // --- Vertical Positioning ---
    // Try to position above the trigger
    let proposedTop = triggerRect.top - tooltipRect.height - gap;

    if (proposedTop < gap) {
        // Not enough space above, position below
        top = triggerRect.bottom + gap;
    } else {
        // Enough space above
        top = proposedTop;
    }

    // --- Horizontal Positioning ---
    // Try to center horizontally
    let proposedLeft = triggerRect.left + (triggerRect.width / 2) - (tooltipRect.width / 2);

    // Check for horizontal viewport collisions
    if (proposedLeft < gap) {
        // Clashes with left edge
        left = gap;
    } else if (proposedLeft + tooltipRect.width > viewportWidth - gap) {
        // Clashes with right edge
        left = viewportWidth - tooltipRect.width - gap;
    } else {
        // It fits
        left = proposedLeft;
    }

    // Apply the new fixed position
    floatingTooltip.style.top = `${top}px`;
    floatingTooltip.style.left = `${left}px`;
}

/**
 * Attaches all necessary event listeners to a *single* tooltip trigger element.
 * This is the core logic we'll re-use.
 */
function activateTooltipTrigger(triggerElement) {
    const tooltipTextElement = triggerElement.querySelector('.tooltip-text');
    
    // Check if there's no text or if it's *already* active
    if (!tooltipTextElement || triggerElement.dataset.tooltipActive === 'true') {
        return; 
    }

    // Get the content and link it to the global tooltip
    const tooltipContent = tooltipTextElement.innerHTML;
    triggerElement.setAttribute('aria-describedby', 'floating-tooltip-global');
    
    // Mark this trigger as "active" to prevent duplicate listeners
    triggerElement.dataset.tooltipActive = 'true';

    // --- Event Listeners ---
    const showTooltip = () => {
        tooltipTrigger = triggerElement; // Set this as the active trigger
        
        // Set content, show, and then position
        floatingTooltip.innerHTML = tooltipContent;
        floatingTooltip.classList.add('show');
        positionTooltip(); // Use our existing positioning function
    };

    const hideTooltip = () => {
        tooltipTrigger = null;
        floatingTooltip.classList.remove('show');
    };

    // Add listeners for both mouse and keyboard
    triggerElement.addEventListener('mouseenter', showTooltip);
    triggerElement.addEventListener('focus', showTooltip);
    triggerElement.addEventListener('mouseleave', hideTooltip);
    triggerElement.addEventListener('blur', hideTooltip);
}

/**
 * Creates the global tooltip element and scans the *entire document*
 * for any tooltips that exist on page load.
 */
function initializeGlobalTooltipSystem() {
    // 1. Create the shared tooltip element and append it to the body
    //    (This part only runs once)
    if (!floatingTooltip) {
        floatingTooltip = document.createElement('div');
        floatingTooltip.className = 'floating-tooltip';
        floatingTooltip.setAttribute('role', 'tooltip');
        floatingTooltip.id = 'floating-tooltip-global';
        document.body.appendChild(floatingTooltip);
        
        // Add a listener to reposition the tooltip on window resize
        window.addEventListener('resize', positionTooltip);
    }

    // 2. Find all tooltip triggers *currently* on the page and activate them
    document.querySelectorAll('.info-tooltip').forEach(activateTooltipTrigger);
}

function renderGroupedPlanQuotes(planData, sector) {
    if (!planData || !Array.isArray(planData) || planData.length === 0) return '';

    // 1. Determine the topic string to filter by
    let topicString = '';
    if (sector === 'childcare') topicString = 'Child Care';
    else if (sector === 'fresh-food') topicString = 'Fresh Food';
    else return '';

    let htmlOutput = '';
    let totalQuotesFound = 0;

    // 2. Iterate through each Plan Area
    planData.forEach(plan => {
        // Safe check for quotes array
        const quotes = Array.isArray(plan.quotes) ? plan.quotes : [];
        
        // 3. Filter quotes within this plan for the specific topic
        const relevantQuotes = quotes.filter(q => q.topic && q.topic.includes(topicString));

        if (relevantQuotes.length > 0) {
            totalQuotesFound += relevantQuotes.length;

            // 4. Create the Header (Area Name + Year)
            // Matches the style of the Incentives headers (uppercase, bold, border)
            htmlOutput += `
                <div class="mt-6 first:mt-2">
                    <h4 class="text-sm font-bold tracking-wider uppercase" style="color: #000000;">
                        ${plan.area_name} <span class="font-normal text-slate-600">${plan.plan_year ? '(' + plan.plan_year + ' plan)' : ''}</span>
                    </h4>
                    <hr class="border-t-2 mt-1 mb-3" style="border-color: #1B1B1B;" />
                    <div class="space-y-4">
            `;

            // 5. Render the quotes
            relevantQuotes.forEach(quote => {
                const categoryText = QUOTE_CATEGORY_MAP[quote.category] || 'Community Voice';
                let tagBg = '#E1F3F8'; // Default: Community Voice
                let tagText = '#28A0CB';

                if (categoryText === 'Community Fact') {
                    tagBg = '#FFE396';
                    tagText = '#936F38';
                } else if (categoryText === 'Individual Voice') {
                    tagBg = '#f2938c';
                    tagText = '#822133';
                }

                htmlOutput += `
                    <div class="text-sm space-y-2" style="font-style: normal;">
                        <div class="bg-white p-4 rounded-lg text-slate-700 leading-relaxed" style="border-radius: 8px; border: 1px solid #e2e8f0;">
                            <div class="mb-2">
                                <span class="quote-category-tag" style="background-color: ${tagBg}; color: ${tagText}; padding: 2px 10px; border-radius: 9999px; font-size: 0.75rem; font-weight: 600;">
                                    ${categoryText}
                                </span>
                            </div>
                            ${quote.briefing_quote}
                        </div>
                    </div>`;
            });

            htmlOutput += `</div></div>`; // Close space-y-4 and wrapper div
        }
    });

    return { html: htmlOutput, count: totalQuotesFound };
}

function slugify(text) {
  return text.toString().toLowerCase()
    .replace(/\s+/g, '-')           // Replace spaces with -
    .replace(/[^\w\-]+/g, '')       // Remove all non-word chars
    .replace(/\-\-+/g, '-')         // Replace multiple - with single -
    .replace(/^-+/, '')             // Trim - from start of text
    .replace(/-+$/, '');            // Trim - from end of text
}

function formatYmd(ymd) {
    if (!ymd || ymd.length !== 8) return 'N/A';
    const year = ymd.substring(0, 4);
    const month = ymd.substring(4, 6);
    const day = ymd.substring(6, 8);
    return `${month}/${day}/${year}`;
}

function truncateCommunityList(listString, maxVisible = 2) {
    if (!listString) return "Unnamed Area";
    const communities = listString.split(', ');
    if (communities.length <= maxVisible) return listString;
    const visibleCommunities = communities.slice(0, maxVisible);
    const hiddenCount = communities.length - maxVisible;
    const communityWord = hiddenCount === 1 ? 'community' : 'communities';
    return `${visibleCommunities.join(', ')} and ${hiddenCount} other ${communityWord}`;
}

function formatGeocoderAddress(addressString) {
    if (!addressString) return { line1: 'Unknown Location', line2: null };

    // 1. Remove ", United States" suffix
    const cleanString = addressString.replace(/, United States$/, '').replace(/, United States of America$/, '');

    // 2. Split by comma
    const parts = cleanString.split(',').map(p => p.trim());

    // 3. Heuristic: If 3 or more parts (Address, City, StateZip), split after first comma
    if (parts.length >= 3) {
        return {
            line1: parts[0],
            line2: parts.slice(1).join(', ')
        };
    }

    // Fallback: Return single line (e.g. "City, State")
    return { line1: cleanString, line2: null };
}

function getMapPadding() {
    const sidePanel = document.getElementById('side-panel');
    const defaultPadding = 50; // A small buffer around the edges of the visible map area

    // If the panel isn't visible, just apply the default buffer
    if (!sidePanel.classList.contains('show')) {
        return { 
            paddingTopLeft: [defaultPadding, defaultPadding], 
            paddingBottomRight: [defaultPadding, defaultPadding] 
        };
    }

    // On mobile, the panel comes from the bottom (50% of the screen height)
    if (window.innerWidth < 768) { 
        const panelHeight = window.innerHeight * 0.5; // Panel is 50vh
        return {
            paddingTopLeft: [defaultPadding, defaultPadding],
            paddingBottomRight: [defaultPadding, panelHeight + defaultPadding] // Add padding to the bottom
        };
    } 
    // On desktop, the panel comes from the left
    else { 
        const panelWidth = sidePanel.offsetWidth;
        return {
            paddingTopLeft: [panelWidth + defaultPadding, defaultPadding], // Add padding to the left
            paddingBottomRight: [defaultPadding, defaultPadding]
        };
    }
}

function zoomToPoint(lat, lng, layerName) {
    // If a provider was previously highlighted, remove the marker
    if (highlightedProviderMarker) {
        map.removeLayer(highlightedProviderMarker);
    }

    const latLng = L.latLng(lat, lng);

    // --- New Logic Start ---

    // 1. Find the actual layer to open its popup
    let targetLayer = null;
    if (layerName && overlayLayers[layerName]) {
        const pointLayer = overlayLayers[layerName];
        // We need to search inside the cluster group for the matching layer
        pointLayer.eachLayer(layer => {
            if (targetLayer) return; // Stop searching if found
            const layerLatLng = layer.getLatLng();
            if (layerLatLng && layerLatLng.lat === lat && layerLatLng.lng === lng) {
                targetLayer = layer;
            }
        });
    }
    
    // 2. Create the highlight marker
    highlightedProviderMarker = L.circleMarker(latLng, {
        radius: 10,
        color: '#005ea2',     // A distinct blue color
        weight: 3,
        opacity: 1,
        fillColor: '#ffffff',
        fillOpacity: 1,
        pane: 'clusterTopPane' // Ensure it's on top
    });

    // 3. Check if point is in view
    const mapBounds = map.getBounds();
    
    if (mapBounds.contains(latLng)) {
        // --- 2a. YES, point is in view ---
        // Just add the marker and open the popup
        highlightedProviderMarker.addTo(map);
        if (targetLayer) {
            // Use a small delay to ensure the popup opens
            setTimeout(() => targetLayer.openPopup(), 100);
        }
    } else {
        // --- 2b. NO, point is not in view ---
        
        // Find the currently selected area
        let selectedBounds = null;
        if (lastClickedLayer) {
            selectedBounds = lastClickedLayer.getBounds();
        } else if (searchMarker) {
            selectedBounds = searchMarker.getLatLng().toBounds(1); // Small bounds around the marker
        }

        let boundsToFit;
        const targetBounds = latLng.toBounds(1); // Small bounds around the target point

        if (selectedBounds) {
            // We have a selected area, so fit both
            boundsToFit = selectedBounds.extend(targetBounds);
        } else {
            // No area is selected, just fit the target point
            boundsToFit = targetBounds;
        }

        // Zoom/pan to fit the combined bounds
        map.fitBounds(boundsToFit, { ...getMapPadding(), maxZoom: 14 });

        // Add the marker and open the popup *after* the map moves
        map.once('moveend', () => {
            highlightedProviderMarker.addTo(map);
            if (targetLayer) {
                targetLayer.openPopup();
            }
        });
    }
    
    // Remove the highlight after a few seconds
    setTimeout(() => {
        if (highlightedProviderMarker) {
            map.removeLayer(highlightedProviderMarker);
        }
    }, 4000);
}

