window.zoomToPoint = zoomToPoint;

function updateGeocoderWidth() {
    const sidePanel = document.getElementById('side-panel');
    const geocoderContainer = document.getElementById('geocoder-container');
    const geocoderInput = document.querySelector('.leaflet-control-geocoder-form input');
    const topControlsRow = document.getElementById('top-left-controls-row');

    // Mobile Logic: Reset styles to allow CSS media queries to take over
    if (window.innerWidth < 768 || !sidePanel || !geocoderContainer) {
        if (geocoderContainer) {
            geocoderContainer.style.width = '';
            geocoderContainer.style.minWidth = '';
        }
        if (geocoderInput) {
            geocoderInput.style.width = '';
            geocoderInput.style.minWidth = '';
        }
        if (topControlsRow) {
            topControlsRow.style.width = '';
            topControlsRow.style.minWidth = '';
        }
        return;
    }

    // Desktop Logic: Match the side panel width
    const panelRect = sidePanel.getBoundingClientRect();
    const panelWidth = panelRect.width;
    
    // The map's top controls wrapper has 1rem (16px) of padding on left and right.
    // To align perfectly with the panel column, we subtract this 32px total padding.
    const totalPadding = 32; 
    const newWidth = panelWidth - totalPadding;

    // 1. Apply width to the Container (so the dropdown list and error div match)
    geocoderContainer.style.width = `${newWidth}px`;
    geocoderContainer.style.minWidth = `${newWidth}px`;

    // 2. Force the Input to match the calculated pixel width.
    // We use pixels here because the parent <form> is inline-block, 
    // so width: 100% would cause it to collapse.
    if (geocoderInput) {
        geocoderInput.style.width = `${newWidth}px`;
        geocoderInput.style.minWidth = `${newWidth}px`;
    }
    
    // 3. Align the buttons above to the same width
    if (topControlsRow) {
        topControlsRow.style.width = `${newWidth}px`;
        topControlsRow.style.minWidth = `${newWidth}px`;
    }
}

function createCustomClusterIcon(cluster) {
    const markers = cluster.getAllChildMarkers();
    const count = cluster.getChildCount();
    
    // 1. Count the types of markers in this cluster
    const typeCounts = {};
    let mostFrequentType = null;
    let maxCount = 0;

    markers.forEach(marker => {
        const type = marker.options.markerType; // We will add this 'markerType' option in Step 4
        if (!type) return;
        
        typeCounts[type] = (typeCounts[type] || 0) + 1;
        
        if (typeCounts[type] > maxCount) {
            maxCount = typeCounts[type];
            mostFrequentType = type;
        }
    });

    // 2. Determine the size class (small, medium, large)
    let sizeClass = ' marker-cluster-';
    if (count < 10) {
        sizeClass += 'small';
    } else if (count < 100) {
        sizeClass += 'medium';
    } else {
        sizeClass += 'large';
    }
    
    // 3. Determine the type class (e.g., 'childcare-cluster')
    const typeClass = mostFrequentType ? ` ${mostFrequentType}-cluster` : '';

    // 4. Create the DivIcon
    return new L.DivIcon({
        html: '<div><span>' + count + '</span></div>',
        className: 'marker-cluster' + sizeClass + typeClass,
        iconSize: new L.Point(40, 40)
    });
}

