function disableMapLayerFocus(layerGroup) {
    if (layerGroup && typeof layerGroup.eachLayer === 'function') {
        layerGroup.eachLayer(function(layer) {
            const element = layer.getElement ? layer.getElement() : layer._icon;
            if (element) {
                element.setAttribute('tabindex', '-1');
                element.setAttribute('inert', 'true');
            }
        });
    }
}

let lastClickedLayer = null;
const sequentialColors = ['#eff3ff', '#bdd7e7', '#6baed6', '#3182bd', '#08519c'];
const divergingColors = [
    '#8c510a',
    '#d8b365',
    '#f6e8c3',
    '#c7eae5',
    '#5ab4ac',
    '#01665e'
];

function isDivergingVariable(variable) {
    const divergingKeywords = ['unmet_demand', 'unmet_market_demand', 'growth', 'net_business', 'formations', 'index', 'pop_change'];
    return divergingKeywords.some(keyword => variable.includes(keyword));
}

function getQuantiles(data, numQuantiles) {
    const sorted = data.filter(v => !isNaN(v)).sort((a, b) => a - b);
    if (sorted.length === 0) return [];
    const quantiles = [];
    for (let i = 1; i < numQuantiles; i++) {
        const pos = (sorted.length - 1) * (i / numQuantiles);
        const base = Math.floor(pos);
        const rest = pos - base;
        if (sorted[base + 1] !== undefined) {
            quantiles.push(sorted[base] + rest * (sorted[base + 1] - sorted[base]));
        } else {
            quantiles.push(sorted[base]);
        }
    }
    return quantiles;
}

function getDivergingBreaks(values) {
    return getQuantiles(values, divergingColors.length);
}

function getColor(d, breaks, colors) {
    if (d > breaks[breaks.length - 1]) return colors[colors.length - 1];
    for (let i = 0; i < breaks.length; i++) {
        if (d <= breaks[i]) return colors[i];
    }
    return colors[0]; // Fallback for values below the first break
}

function style(feature) {
    let currentVariable = choroplethSelect.value;
    const isDiverging = isDivergingVariable(currentVariable);
    const breaks = choroplethBreaks[currentVariable];
    
    let baseStyle;

    if (!breaks || breaks.length === 0) {
        baseStyle = { fillColor: '#636363', weight: 0, color: 'white', fillOpacity: 1, pane: 'tractPane' };
    } else {
        const colors = isDiverging ? divergingColors : sequentialColors;
        const value = safeParseFloat(feature.properties[currentVariable]);
        baseStyle = {
            fillColor: (value === null) ? '#636363' : getColor(value, breaks, colors),
            weight: 0, opacity: 1, color: 'white', fillOpacity: 1, pane: 'tractPane'
        };
    }
    
    // Check if this feature is the one that's currently clicked/selected
    if (lastClickedLayer && feature === lastClickedLayer.feature) {
        // If it is, override the weight and color to show the highlight
        baseStyle.weight = 4;
        baseStyle.color = '#FFFFFF';
        baseStyle.dashArray = '';
    }

    return baseStyle;
}

function updateMap() {
    if (geojsonLayer) geojsonLayer.setStyle(style);
    
    // Ensure the legend control exists on the map
    if (legend && !legend._map) {
        legend.addTo(map);
    }
    
    // Trigger a re-render of the legend content
    renderLegendContent();
}

function highlightFeature(e) {
    const layer = e.target;
    layer.setStyle({ weight: 4, color: '#FFFFFF', dashArray: '' });
}

function resetHighlight(e) { 
    if (lastClickedLayer !== e.target) {
        geojsonLayer.resetStyle(e.target);
    }
    // After any mouseout event, ensure the selected layer is brought back to the front.
    if (lastClickedLayer) {
        lastClickedLayer.bringToFront();
    }
}

function onEachFeature(feature, layer) {
    layer.on({
        mouseover: function (e) {
            if (L.Browser.mobile) {
                return;
            }
            if (isPanning) {
                return;
            }

            const feature = e.target.feature;
            const currentVariable = choroplethSelect.value;
            const option = CHOROPLETH_OPTIONS[currentVariable];
            let dataRow = '';

            if (option && currentVariable !== 'none') {
                const rawValue = feature.properties[currentVariable];
                const formattedValue = (rawValue === null || rawValue === undefined) ? 'N/A' : option.format(rawValue);
                let extraInfo = '';
                if (currentVariable === 'pop_change2530') {
                    const pctValue = feature.properties.pop_change2530_pct_change;
                    const formattedPct = (pctValue === null || pctValue === undefined) ? 'N/A' : formatPercent(pctValue);
                    extraInfo = `&nbsp;(${formattedPct})`;
                }
                dataRow = `
                    <hr class="my-1 border-t border-slate-300">
                    <div class="text-sm text-slate-800">${option.label}: <strong>${formattedValue}${extraInfo}</strong></div>
                `;
            }
            const dynamicTooltipContent = `
                <div class="font-sans">
                    <div class="text-xs uppercase font-semibold text-slate-500 tracking-wider">Click map to Research</div>
                    <div class="text-lg font-bold text-slate-900 leading-tight mt-1">${truncateCommunityList(feature.properties.tract_name)}</div>
                    <div class="text-base text-blue-700 font-semibold">${feature.properties.county_name}</div>
                    ${dataRow}
                </div>
            `;
            
            globalTooltipElement.innerHTML = dynamicTooltipContent;
            L.DomUtil.removeClass(globalTooltipElement, 'hidden');

            positionGlobalMapTooltip(e);

            highlightFeature(e);
        },
        mousemove: function(e) {
            positionGlobalMapTooltip(e);
        },

        mouseout: function (e) {
            // Just hide the single global tooltip.
            L.DomUtil.addClass(globalTooltipElement, 'hidden');
            resetHighlight(e);
        },

        click: (e) => {
            const geocoderInput = document.querySelector('#geocoder-container .leaflet-control-geocoder-form input');
            const clearBtn = document.getElementById('geocoder-clear-btn');
            const geocoderContainer = document.getElementById('geocoder-container');
            if (geocoderInput) {
                geocoderInput.value = ''; // Clear any typed text
                // Set placeholder to the clicked tract name
                geocoderInput.placeholder = truncateCommunityList(feature.properties.tract_name);
                resetGeocoderUI();
            }
            if (clearBtn) {
                clearBtn.classList.remove('hidden');
                clearBtn.classList.add('visible');
            }

            const clickedLayer = e.target;

            // GA4 & State: Save Tract Data on Click
            saveLastViewedTract(feature.properties);
            logGaEvent('tract_click', {
                geoid: feature.properties.GEOID,
                tract_name: feature.properties.tract_name,
                county_name: feature.properties.county_name
            });

            if (searchMarker) {
                map.removeLayer(searchMarker);
                searchMarker = null;
            }

            if (lastClickedLayer === clickedLayer) {
                return;
            }
            const previouslyClickedLayer = lastClickedLayer;
            lastClickedLayer = clickedLayer;

            if (previouslyClickedLayer) {
                geojsonLayer.resetStyle(previouslyClickedLayer);
            }

            lastClickedLayer.setStyle({
                weight: 4,
                color: '#FFFFFF',
                dashArray: ''
            });

            lastClickedLayer.bringToFront();

            if (currentMapMode === 'smartResearch') {
                displaySmartResearchForTract(feature);
            } else {
                displayFeatureInfo(feature);
            }
            map.fitBounds(clickedLayer.getBounds(), { ...getMapPadding(), maxZoom: 14 });
        }
    });
}

