function clearProviderLayers() {
    // 1. Identify all point layers from the configuration
    const pointConfigs = OVERLAY_CONFIG.filter(c => c.type === 'point');
    
    pointConfigs.forEach(cfg => {
        const name = cfg.name;
        
        // 2. Remove the layer from the map model if it's currently added
        if (overlayLayers[name] && map.hasLayer(overlayLayers[name])) {
            map.removeLayer(overlayLayers[name]);
        }

        // 3. Sync the UI: Uncheck the box if it exists in the DOM (e.g., Edit Mode)
        const checkbox = document.querySelector(`input.overlay-toggle-input[data-name="${name}"]`);
        if (checkbox) {
            checkbox.checked = false;
        }
    });

    // 4. Refresh the Legend View to remove the "Active Keys" (dots) immediately
    if (!isLegendEditing) {
        renderLegendContent();
    }
}

function filterIncentives(industry, location) {
    if (!location || !allIncentives) return [];
    const county = (location.type === 'tract' ? location.feature.properties.county_name : location.tractProps.county_name).replace(' County', '').trim();
    const reverseIncentiveMap = Object.fromEntries(Object.entries(INCENTIVE_AREA_MAP).map(([key, value]) => [value, key]));

    // Use .map and .filter to return a modified list of incentives
    return allIncentives.map(inc => {
        const eligibleOrganizationTypes = inc.eligible_organization_types || [];
        if (!eligibleOrganizationTypes.includes('for-profit')) return null;
        const assistanceTypes = inc.assistance_type || [];
        if (assistanceTypes.length == 1 && assistanceTypes.includes('support')) {
            return null;
        }

        const eligibleIndustries = inc.list_of_eligible_industries || [];
        const prioritizedIndustries = inc.list_of_prioritized_industries || [];
        const industryMatch = eligibleIndustries.includes(industry) || prioritizedIndustries.includes(industry);
        if (!industryMatch) return null;

        const eligibleCounties = inc.list_of_eligible_counties || [];
        const prioritizedCounties = inc.list_of_prioritized_counties || [];
        const countyMatch = eligibleCounties.includes('All') || eligibleCounties.includes(county) || prioritizedCounties.includes('All') || prioritizedCounties.includes(county);

        const incentiveAreas = inc.list_of_incentive_areas || [];
        let matchingIncentiveAreas = []; // <-- Capture all matching areas

        if (incentiveAreas.length > 0) {
            if (location.type === 'tract') {
                const tractFeature = location.feature;
                // Directly get the pre-calculated list of overlaps from the tract's properties.
                const precalculatedOverlaps = tractFeature.properties.incentive_areas || [];

                // Filter the incentive's required areas against the tract's known overlaps.
                matchingIncentiveAreas = incentiveAreas.filter(humanName => 
                    precalculatedOverlaps.includes(humanName)
                );

            } else if (location.type === 'point') { // This part stays the same
                matchingIncentiveAreas = incentiveAreas.filter(humanName => {
                    const layerName = reverseIncentiveMap[humanName];
                    const layer = overlayLayers[layerName];
                    return layer && isPointInLayer_Turf(location.point, layer);
                });
            }
        }
        
        // Only return the incentive if it matches by county OR has matching incentive areas
        if (countyMatch || matchingIncentiveAreas.length > 0) {
            // Return a copy of the incentive with the matching areas attached
            return { ...inc, matchingIncentiveAreas };
        }

        return null;
    }).filter(Boolean); // Filter out the null values
}

function createIncentiveListHTML(incentives, type, industry, county) {
    if (!incentives || incentives.length === 0) {
        return `<p class="text-sm text-slate-600 mt-2">No specific ${type.toLowerCase()} incentives found for this area.</p>`;
    }

    // --- New Grouping Logic ---
    const groupedIncentives = {
        GRANTS: [],
        LOANS: [],
        TAX_CREDITS: []
    };

    incentives.forEach(inc => {
        const types = inc.assistance_type || [];
        // Use .some() to check for partial matches like "loan guarantee"
        const hasGrant = types.some(t => t.toLowerCase().includes('grant'));
        const hasLoan = types.some(t => t.toLowerCase().includes('loan'));
        const hasTaxCredit = types.some(t => t.toLowerCase().includes('tax-credit'));

        // Prioritize: Grant > Loan > Tax Credit
        if (hasGrant) {
            groupedIncentives.GRANTS.push(inc);
        } else if (hasLoan) {
            groupedIncentives.LOANS.push(inc);
        } else if (hasTaxCredit) {
            groupedIncentives.TAX_CREDITS.push(inc);
        }
    });

    // --- HTML Generation Logic ---
    let html = '';
    const groupOrder = ['GRANTS', 'LOANS', 'TAX_CREDITS'];
    
    // Helper function to create the HTML for a single incentive
    const createIncentiveHTML = (inc) => {
        const params = new URLSearchParams();
        params.set('industries', industry);
        params.set('counties', county);
        params.set('orgTypes', 'for-profit');
        const queryString = params.toString();

        // Note: py-3 and border-b create the padded separator effect
        return `
            <div class="text-sm py-3 border-b border-[#DFE1E2] last:border-b-0">
                <p class="font-bold text-slate-800">
                    <a href="../incentives/?${queryString}#/incentive/${slugify(inc.program_name)}" target="_blank" rel="noopener noreferrer" class="text-blue-600 hover:underline">
                        ${inc.program_name}
                    </a> 
                </p>
                <p class="text-slate-600 mt-1">${inc.program_description}</p>
            </div>
        `;
    };

    // Loop through the groups in order and build the HTML
    groupOrder.forEach(groupName => {
        const groupItems = groupedIncentives[groupName];
        if (groupItems.length > 0) {
            html += `
                <div class="mt-4">
                    <h4 class="text-sm font-bold tracking-wider uppercase" style="color: #000000;">
                        ${groupName.replace('_', '-')}
                    </h4>
                    <hr class="border-t-2 mt-1 mb-0" style="border-color: #1B1B1B;" />
                    <div class="space-y-0">
                        ${groupItems.map(createIncentiveHTML).join('')}
                    </div>
                </div>
            `;
        }
    });

    if (html === '') {
        return `<p class="text-sm text-slate-600 mt-2">No specific grants, loans, or tax credits found for this area.</p>`;
    }
    
    return html;
}

function renderBreaksVisualizer(value, variableName) {
    // 1. Get Breaks
    const breaks = choroplethBreaks[variableName];
    if (!breaks || breaks.length === 0) return '';

    // 2. Determine Color Scale (Diverging or Sequential)
    const isDiverging = isDivergingVariable(variableName);
    const colors = isDiverging ? divergingColors : sequentialColors;

    // 3. Determine which bin index (0 to N) the value falls into
    let binIndex = 0;
    // Breaks logic: if value <= breaks[0], index 0. If > breaks[0] && <= breaks[1], index 1...
    // If value > last break, index = length
    for (let i = 0; i < breaks.length; i++) {
        if (value <= breaks[i]) {
            binIndex = i;
            break;
        }
        if (i === breaks.length - 1) {
            binIndex = i + 1; // The value is greater than the last break
        }
    }

    // 4. Generate Segments HTML
    // Total segments = number of breaks + 1 (for the upper bound)
    // BUT: Your colors array length usually matches the number of bins.
    // Let's ensure we don't overflow the colors array.
    const totalSegments = colors.length;
    
    // Safety clamp
    if (binIndex >= totalSegments) binIndex = totalSegments - 1;

    let segmentsHTML = '';
    for (let i = 0; i < totalSegments; i++) {
        // Active segment gets the color, inactive gets gray
        const bgStyle = (i === binIndex) ? `background-color: ${colors[i]};` : '';
        // Optional: Highlight active segment with a darker border or slightly larger size?
        // For now, just color match as per screenshot.
        segmentsHTML += `<div class="visualizer-segment" style="${bgStyle}"></div>`;
    }

    return `<div class="visualizer-container">${segmentsHTML}</div>`;
}

