async function showNearestPoints(location, layerName, container) {
    // --- 1. Ensure Layer Data is Loaded (Without forcing map display) ---
    // Unlike the previous version, we do NOT toggle the checkbox or force map.addLayer.
    // We only ensure the data exists in 'overlayLayers' so we can query it.

    if (!overlayLayers[layerName]) {
        const config = OVERLAY_CONFIG.find(c => c.name === layerName);
        if (config) {
             try {
                const response = await fetch(config.url);
                if (!response.ok) throw new Error(`Failed to load ${config.url}`);
                const data = await response.json();

                // Create the layer in memory but DO NOT add it to the map yet.
                overlayLayers[layerName] = createPointLayer(data, layerName);
             } catch (e) {
                console.error(e);
                container.innerHTML = `<p class="text-sm text-red-600">Could not load location data.</p>`;
                return;
             }
        } else {
             container.innerHTML = `<p class="text-sm text-red-600">Configuration missing for ${layerName}.</p>`;
             return;
        }
    }

    const pointLayer = overlayLayers[layerName];
    if (!pointLayer) {
        container.innerHTML = `<p class="text-sm text-red-600">Could not load location data.</p>`;
        return;
    }

    // --- 2. Find Relevant Providers ---
    // Note: pointLayer.getLayers() works on the ClusterGroup even if it's not on the map.
    // 1. Cache the flat list to avoid expensive getLayers() calls on every click
    if (!pointLayer._cachedFlatPoints) {
        pointLayer._cachedFlatPoints = pointLayer.getLayers().map(l => ({
            layer: l,
            // Pre-calculate coordinates to avoid repetitive access
            lat: l.getLatLng().lat,
            lng: l.getLatLng().lng,
            feature: l.feature || { properties: l.options.properties, geometry: { coordinates: [l.getLatLng().lng, l.getLatLng().lat] } }
        }));
    }
    const allPoints = pointLayer._cachedFlatPoints;

    let relevantProviders = [];
    let targetPoint; // [lng, lat]
    let locationContext;
    
    // 2. Define "Cheap" Pre-filter Buffers
    // TRACTS: Calculated via R to be ~0.367 deg (Max centroid-to-edge dist + 1 mile). 
    // We use 0.37 to be safe.
    const TRACT_PRE_FILTER_BUFFER = 0.37; 
    
    // POINTS: We only need 1 mile (~0.015 deg). We use 0.02 to be safe and fast.
    const POINT_PRE_FILTER_BUFFER = 0.02;

    if (location.type === 'tract') {
        const tractPolygon = location.feature;
        targetPoint = turf.centroid(tractPolygon).geometry.coordinates; 
        const targetLng = targetPoint[0];
        const targetLat = targetPoint[1];
        
        locationContext = "within 1 mile of this community"; 

        // A. Cheap Pre-filter (using the calculated safety buffer)
        // This eliminates points that are mathematically impossible to be within range.
        const candidates = allPoints.filter(p => 
            Math.abs(p.lat - targetLat) < TRACT_PRE_FILTER_BUFFER && 
            Math.abs(p.lng - targetLng) < TRACT_PRE_FILTER_BUFFER
        );

        // B. Expensive Calculation on subset only
        const candidatesWithDist = candidates.map(p => ({
            ...p,
            distance: turf.distance(targetPoint, p.feature.geometry.coordinates, { units: 'miles' })
        }));

        const tractLine = turf.polygonToLine(tractPolygon);

        relevantProviders = candidatesWithDist.filter(p => {
            const pointCoords = p.feature.geometry.coordinates;
            // Check if inside polygon
            const isInside = turf.booleanPointInPolygon(pointCoords, tractPolygon);
            if (isInside) return true;
            // Or check distance to edge
            const distanceToEdge = turf.pointToLineDistance(pointCoords, tractLine, { units: 'miles' });
            return distanceToEdge <= 1;
        });

    } else if (location.type === 'point') {
        targetPoint = [location.point.lng, location.point.lat]; 
        const targetLng = targetPoint[0];
        const targetLat = targetPoint[1];

        locationContext = "within 1 mile of this address"; 

        // A. Cheap Pre-filter (Tight buffer for single points)
        const candidates = allPoints.filter(p => 
            Math.abs(p.lat - targetLat) < POINT_PRE_FILTER_BUFFER && 
            Math.abs(p.lng - targetLng) < POINT_PRE_FILTER_BUFFER
        );

        // B. Expensive Calculation on subset only
        const candidatesWithDist = candidates.map(p => ({
            ...p,
            distance: turf.distance(targetPoint, p.feature.geometry.coordinates, { units: 'miles' })
        }));

        relevantProviders = candidatesWithDist.filter(p => p.distance <= 1);

    } else {
        container.innerHTML = `<p class="text-sm text-red-600">Invalid location type.</p>`;
        return;
    }

    relevantProviders.sort((a, b) => a.distance - b.distance);

    const listContainer = container.querySelector('#nearest-providers-list');
    const totalProviders = relevantProviders.length;

    // --- 3. Render List ---
    let introText = `<p class="text-sm text-ink pb-2">There are <strong>${totalProviders}</strong> locations found ${locationContext}.</p>`;

    if (totalProviders === 0) {
        listContainer.innerHTML = introText;
        return;
    }

    const itemsPerPage = 10;
    const totalPages = Math.ceil(totalProviders / itemsPerPage);
    const needsPagination = totalProviders > itemsPerPage;
    let currentPage = 1;
    let paginationText = '';

    if (needsPagination) {
        paginationText = `<p class="text-sm text-slate-600 mt-1 pagination-text">Showing 1-${Math.min(itemsPerPage, totalProviders)} of ${totalProviders} locations</p>`;
    }

    const providerIcon = layerName === 'childcare' ? ICONS.childcareProvider : ICONS.freshFoodProvider;

    const listHtml = relevantProviders.map((p, index) => {
        const popupContent = p.layer.getPopup().getContent();
        const nameRegex = /<div class="font-bold text-lg leading-tight">(.*?)<\/div>/;
        const name = safeMatch(popupContent, nameRegex, 1, 'Unnamed Location');
        const latlng = p.layer.getLatLng();

        const quality = p.feature.properties.quality;
        const q = (quality != null) ? Number(quality) : null;
        let qualityText = '';

        if (layerName === 'childcare') {
            qualityText = (q === null || isNaN(q)) ? '' : (q === 0 ? 'Not rated' : `Quality: ${q}`);
        } else if (layerName === 'grocery') {
            const groceryLabels = { 2: 'Convenience', 3: 'Specialty foods', 4: 'Specialty foods', 5: 'Fresh produce' };
            qualityText = (q === null || isNaN(q)) ? '' : (groceryLabels[q] || `Quality: ${q}`);
        } else {
            qualityText = (quality != null) ? `Quality: ${quality}` : '';
        }

        const distanceText = `${p.distance.toFixed(1)} miles`; 
        let detailsText = (distanceText && qualityText) ? `${distanceText} &nbsp;&bull;&nbsp; ${qualityText}` : (distanceText || qualityText);

        const isHidden = (needsPagination && index >= itemsPerPage) ? 'hidden' : '';

        return `
            <li data-provider-item="true" class="flex items-start gap-3 py-3 ${isHidden}" data-quality="${quality ?? ''}">
                <div class="flex-shrink-0 pt-0.5">${providerIcon}</div>
                <div class="flex-grow">
                    <a href="javascript:void(0);" 
                       onclick="zoomToPoint(${latlng.lat}, ${latlng.lng}, '${layerName}')"
                       class="font-semibold text-slate-800 hover:underline focus:underline focus:outline-none">
                        ${name}
                    </a>
                    <p class="text-sm text-slate-700 mt-0.5">${detailsText}</p>
                </div>
            </li>`;
    }).join('');

    listContainer.innerHTML = `
        <div class="providers-container" id="provider-list-container-${layerName}">
            ${introText}
            ${paginationText}
            <ul class="mt-2 -my-3 divide-y divide-[#DFE1E2]">
                ${listHtml}
            </ul>
            <div class="pagination-nav-container mt-4">
                ${needsPagination ? renderPagination(totalPages, currentPage, `provider-list-container-${layerName}`, layerName) : ''}
            </div>
        </div>
    `;
}
    
async function queryParcelData(longitude, latitude) {
    const url = `https://api.mapbox.com/v4/${TILESET_ID}/tilequery/${longitude},${latitude}.json?access_token=${MAPBOX_ACCESS_TOKEN}`;
    try {
        const response = await fetch(url);
        if (!response.ok) throw new Error('Tilequery request failed');
        const data = await response.json();
        const parcel = data.features.find(f => f.properties.tilequery.layer === 'parcels_0825');
        return parcel ? parcel.properties : null;
    } catch (error) {
        console.error("Error fetching parcel data:", error);
        return null;
    }
}

function findTractForPoint(latlng) {
    let found = null;
    if (geojsonLayer) {
        geojsonLayer.eachLayer(layer => {
            if (!found && isPointInLayer_Turf(latlng, layer)) found = layer.feature;
        });
    }
    return found;
}

