function isPointInLayer_Turf(point, layer) {
    if (!point || !layer) return false;
    const turfPoint = [point.lng, point.lat];
    const geojson = layer.toGeoJSON();
    try {
        if (geojson.type === 'FeatureCollection') {
            for (const feature of geojson.features) {
                if (turf.booleanPointInPolygon(turfPoint, feature)) return true;
            }
            return false;
        } else {
            return turf.booleanPointInPolygon(turfPoint, geojson);
        }
    } catch (e) {
        console.error("Turf.js failed to process a geometry.", e, geojson);
        return false;
    }
}

